// Get the infinite face and mark it as exterior
auto infinite_face = triangulation.infinite_face();
infinite_face->info().is_exterior = true;

// Use BFS/DFS to propagate labels
std::queue<Face_handle> face_queue;
face_queue.push(infinite_face);

while (!face_queue.empty()) {
    Face_handle face = face_queue.front();
    face_queue.pop();

    for (int i = 0; i < 3; i++) {
        Face_handle neighbor = face->neighbor(i);

        // Check if neighbor is already labeled
        if (neighbor->info().is_exterior.has_value()) {
            continue;
        }

        // Check if the edge is a constraint
        if (triangulation.is_edge_constrained(face, i)) {
            // If crossing a constraint, flip the label
            neighbor->info().is_exterior = !face->info().is_exterior;
        } else {
            // If not a constraint, same label
            neighbor->info().is_exterior = face->info().is_exterior;
        }

        face_queue.push(neighbor);
    }
}

